.d-ripplegl{width:100%;min-height:510px;box-sizing:border-box;padding:20px clamp(8px,4vw,34px) 16px;color:#edf2f1;background:#080b0c;font-family:Roboto Mono,JetBrains Mono,monospace}.d-ripplegl-head{display:flex;justify-content:space-between;color:#687276;font:700 9px/1.2 ui-monospace,monospace;letter-spacing:.12em}.d-ripplegl-head b{color:#78ead0}.d-ripplegl-head i{color:#d3dcda;font-style:normal}.d-ripplegl-field{position:relative;height:390px;margin-top:13px;overflow:hidden;border:1px solid #222c2e;background:radial-gradient(circle at 45% 45%,#254e4b,#111b1d 58%,#091013)}.d-ripplegl canvas{display:block;width:100%;height:100%;outline:none;cursor:crosshair}.d-ripplegl canvas:focus-visible{box-shadow:inset 0 0 0 2px #9bf4df}.d-ripplegl-cross{position:absolute;left:50%;top:50%;pointer-events:none;opacity:.35}.d-ripplegl-cross i{position:absolute;background:#b7e6db}.d-ripplegl-cross i:first-child{left:-16px;top:0;width:32px;height:1px}.d-ripplegl-cross i:last-child{left:0;top:-16px;width:1px;height:32px}.d-ripplegl-coords{position:absolute;right:13px;top:12px;color:rgba(225,242,238,.55);font:650 7px/1 ui-monospace,monospace;letter-spacing:.09em;pointer-events:none}.d-ripplegl-coords b{color:#d5ece7}.d-ripplegl-label{position:absolute;left:13px;bottom:11px;color:rgba(216,235,231,.48);font:650 6px/1 ui-monospace,monospace;letter-spacing:.1em;pointer-events:none}.d-ripplegl-fallback{display:none;position:absolute;inset:0;place-items:center;margin:0;color:#a7c2bc;font:650 9px/1 ui-monospace,monospace}.d-ripplegl.no-webgl .d-ripplegl-fallback{display:grid}.d-ripplegl.no-webgl canvas{opacity:0}.d-ripplegl-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:12px}.d-ripplegl-foot p{margin:0;color:#727e80;font:650 9px/1.3 ui-monospace,monospace}.d-ripplegl-foot button{min-height:31px;padding:7px 11px;border:1px solid #313d3f;border-radius:3px;color:#a2adaf;background:#111719;font:700 8px/1 ui-monospace,monospace;text-transform:uppercase;cursor:pointer}.d-ripplegl-foot button:hover,.d-ripplegl-foot button:focus-visible{color:#fff;border-color:#68797b;outline:none}@media(max-width:550px){.d-ripplegl{padding-inline:6px}}
.d-ripplegl{height:320px;min-height:0;padding:14px 14px 10px;background:#0a0a0b;container-type:inline-size}.d-ripplegl-field{height:240px;margin-top:10px}.d-ripplegl [class$="-head"]{font-size:8px;line-height:1.3;letter-spacing:.02em;gap:10px}.d-ripplegl [class$="-head"]>span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.d-ripplegl [class$="-head"]>span:last-child{flex-shrink:0}.d-ripplegl [class$="-foot"]{margin-top:8px;gap:8px;font-size:8px}.d-ripplegl [class$="-foot"] p{font-size:8px;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.d-ripplegl [class$="-foot"] button{font-size:8px;min-height:24px;padding:5px 8px;border-radius:0;flex-shrink:0}.d-ripplegl [class$="-head"] b{color:#fa7319}@container(max-width:350px){.d-ripplegl [class$="-head"]>span:first-child{max-width:46%}}
.d-ripplegl{width:100%;height:320px;min-height:0;box-sizing:border-box;position:relative;padding:0;display:block;background:#e7eae2;color:#778469;font-family:"Inter",system-ui,sans-serif;overflow:hidden}.d-ripplegl [class$="-head"]{display:none}.d-ripplegl>[class$="-field"],.d-ripplegl>[class$="-scene"],.d-ripplegl>[class$="-stage"]{position:absolute;inset:0 0 48px;width:100%;height:auto;min-height:0;margin:0;border:0;border-radius:0;box-shadow:none}.d-ripplegl [class$="-foot"]{position:absolute;left:12px;right:12px;bottom:10px;height:28px;margin:0;display:flex;justify-content:center;align-items:center;padding:0;gap:8px}.d-ripplegl [class$="-foot"] p,.d-ripplegl [class$="-status"]{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.d-ripplegl [class$="-foot"] button{min-height:28px;height:28px;font:400 10px "Inter",system-ui,sans-serif;letter-spacing:0;text-transform:none;padding:5px 12px;border:1px solid #a6b89550;border-radius:15px;background:none;color:#7b8f67;box-shadow:none;cursor:pointer}.d-ripplegl [class$="-note"],.d-ripplegl [class$="-scale"],.d-ripplegl [class$="-coords"],.d-ripplegl [class$="-reticle"],.d-ripplegl [class$="-axis"],.d-ripplegl [class$="-vector"],.d-ripplegl [class$="-depth"],.d-ripplegl [class$="-cross"],.d-ripplegl [class$="-tags"]{display:none}.d-ripplegl button:focus-visible,.d-ripplegl canvas:focus-visible{outline:2px solid #a4b890;outline-offset:-3px}.d-ripplegl [class$="-label"],.d-ripplegl [class$="-side"],.d-ripplegl [class$="-spec"],.d-ripplegl [class$="-measure"]{display:none}
